export class AudioEngine{
 constructor(){this.context=null;this.buffer=null;this.source=null;this.analysis=null;this.offset=0;this.startTime=0;this.rate=1;this.playing=false;this.loading=false;this.eventIndex=0;this.muted=false;this.serial=0;this.title='';this.voices=[];this.noteCounts=[0,0,0,0,0,0];this.octave=0;}
 async unlock(){if(!this.context){const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)throw Error('This browser does not support Web Audio');this.context=new Audio();this.master=this.context.createGain();this.master.gain.value=.5;this.master.connect(this.context.destination);}await this.context.resume();}
 get position(){return Math.min(this.buffer?.duration||0,this.offset+(this.playing?(this.context.currentTime-this.startTime)*this.rate:0));}
 async load(data,title){if(this.loading)throw Error('Analyzing audio. Please wait.');this.loading=true;try{await this.unlock();const buffer=await this.context.decodeAudioData(data.slice(0));if(buffer.duration>600)throw Error('Choose a recording shorter than ten minutes');const mono=new Float32Array(buffer.length);for(let c=0;c<buffer.numberOfChannels;c++){const values=buffer.getChannelData(c);for(let i=0;i<mono.length;i++)mono[i]+=values[i]/buffer.numberOfChannels;}
  const analysis=await new Promise((resolve,reject)=>{const worker=new Worker(new URL('./analyzer-worker.js',import.meta.url));worker.onmessage=e=>{worker.terminate();e.data.error?reject(Error(e.data.error)):resolve(e.data);};worker.onerror=e=>{worker.terminate();reject(Error(e.message||'Audio analysis failed'));};worker.postMessage({mono,sampleRate:buffer.sampleRate},[mono.buffer]);});
  this.pause();this.buffer=buffer;this.analysis=analysis;this.title=title;this.offset=0;this.eventIndex=0;this.rate=1;this.start();return analysis;
 }finally{this.loading=false;}}
 start(){if(!this.buffer)return;this.stopSource();if(this.offset>=this.buffer.duration-.01)this.offset=0;const source=this.context.createBufferSource();source.buffer=this.buffer;source.playbackRate.value=this.rate;source.connect(this.master);const serial=++this.serial;source.onended=()=>{if(this.serial===serial&&this.playing){this.offset=this.buffer.duration;this.playing=false;}};this.source=source;this.startTime=this.context.currentTime;this.playing=true;source.start(0,this.offset);this.eventIndex=this.analysis.events.findIndex(e=>e.time>=this.offset);if(this.eventIndex<0)this.eventIndex=this.analysis.events.length;}
 stopSource(){this.serial++;if(this.source){try{this.source.stop();}catch{}this.source.disconnect();this.source=null;}}
 pause(){if(this.playing)this.offset=this.position;this.playing=false;this.stopSource();}
 async toggle(){await this.unlock();if(this.playing)this.pause();else this.start();}
 seek(position){const was=this.playing;this.pause();this.offset=Math.max(0,Math.min(this.buffer.duration,position));if(was)this.start();else{this.eventIndex=this.analysis.events.findIndex(e=>e.time>=this.offset);if(this.eventIndex<0)this.eventIndex=this.analysis.events.length;}}
 setRate(rate){if(!this.context)return;rate=Math.max(.25,Math.min(1.8,rate));if(Math.abs(rate-this.rate)<.0001)return;const now=this.position;this.offset=now;this.startTime=this.context.currentTime;this.rate=rate;if(this.source)this.source.playbackRate.setTargetAtTime(this.rate,this.context.currentTime,.025);}
 mute(){this.muted=!this.muted;if(this.master)this.master.gain.setTargetAtTime(this.muted?0:.5,this.context.currentTime,.02);return this.muted;}
 sample(){if(!this.analysis||!this.playing)return [0,0,0];const a=this.analysis,p=Math.min(a.levels.length/3-1,this.position*a.fps),i=Math.floor(p),j=Math.min(i+1,a.levels.length/3-1),f=p-i;return [0,1,2].map(b=>a.levels[i*3+b]*(1-f)+a.levels[j*3+b]*f);}
 takeEvents(){if(!this.playing||!this.analysis)return [];const t=this.position,result=[];while(this.eventIndex<this.analysis.events.length&&this.analysis.events[this.eventIndex].time<=t){const e=this.analysis.events[this.eventIndex++];if(t-e.time<.15)result.push(e);}return result;}
 async note(voice,velocity=.7,deck=0,crossfade=.45,fx=[.5,.3]){await this.unlock();const ctx=this.context,t=ctx.currentTime,chordIndex=Math.floor((this.playing?this.position:ctx.currentTime)/(60/108*8))%4,chords=[[50,53,57,60,64],[50,53,57,60,62],[53,57,60,64,67],[48,52,55,62,67]],roots=[38,34,41,36],chord=chords[chordIndex],order=[0,2,3,1,4,3,2,0],count=this.noteCounts[voice]++,midi=chord[order[count%8]]+12+this.octave*12,frequency=n=>440*2**((n-69)/12),gain=Math.max(0,velocity)*.18*(deck?Math.sin(crossfade*Math.PI/2):Math.cos(crossfade*Math.PI/2));
  const env=ctx.createGain();env.connect(this.master);env.gain.setValueAtTime(.0001,t);env.gain.exponentialRampToValueAtTime(Math.max(.0002,gain),t+.012);const length=[.5,1.3,2.8,1.,1.,.16][voice];env.gain.exponentialRampToValueAtTime(.0001,t+length);
  if(voice===5){const buffer=ctx.createBuffer(1,ctx.sampleRate*.18,ctx.sampleRate),samples=buffer.getChannelData(0);for(let i=0;i<samples.length;i++)samples[i]=(Math.random()*2-1)*Math.exp(-i/ctx.sampleRate*25);const source=ctx.createBufferSource(),filter=ctx.createBiquadFilter();filter.type='highpass';filter.frequency.value=2400;source.buffer=buffer;source.connect(filter);filter.connect(env);source.start();source.stop(t+.2);}else{
   const pitches=voice===2?chord:[voice===4?roots[chordIndex]+[0,7,12,7][count%4]:voice===0?36:midi];for(const n of pitches){const osc=ctx.createOscillator(),part=ctx.createGain();osc.type=voice===3?'triangle':'sine';osc.frequency.value=frequency(n);part.gain.value=1/pitches.length;if(voice===0){osc.frequency.setValueAtTime(100,t);osc.frequency.exponentialRampToValueAtTime(37,t+.1);}osc.connect(part);part.connect(env);osc.start(t);osc.stop(t+length+.05);}
  }
  if(fx[1]>.3){const delay=ctx.createDelay(),wet=ctx.createGain();delay.delayTime.value=.19;wet.gain.value=fx[1]*.15;env.connect(delay);delay.connect(wet);wet.connect(this.master);setTimeout(()=>{delay.disconnect();wet.disconnect();env.disconnect();},(length+1)*1000);}else setTimeout(()=>env.disconnect(),(length+.1)*1000);
 }
}
